// Disposable review harness. The production classifier is included unchanged.
// Only its UTF-8 path wrapper is substituted with std::path::Path.
extern crate self as camino;
pub type Utf8Path = std::path::Path;
#[path = "../crates/fs/executor/src/reconcile.rs"]
mod reconcile;
use std::os::unix::fs::PermissionsExt;
fn main() {
    let root = std::path::PathBuf::from(std::env::args().nth(1).expect("fixture directory"));
    std::fs::create_dir(&root).unwrap();
    let private = root.join("private");
    std::fs::create_dir(&private).unwrap();
    let source = private.join("unchanged.fit");
    std::fs::write(&source, b"sentinel remains").unwrap();
    std::fs::set_permissions(&private, std::fs::Permissions::from_mode(0)).unwrap();
    let probe = std::fs::symlink_metadata(&source).unwrap_err().kind();
    let verdict = reconcile::classify(reconcile::MutationShape::Remove, Some(&source), None);
    std::fs::set_permissions(&private, std::fs::Permissions::from_mode(0o700)).unwrap();
    assert_eq!(std::fs::read(&source).unwrap(), b"sentinel remains");
    println!("metadata={probe:?}; production_classify={verdict:?}; source_bytes_unchanged=true");
    assert_eq!(probe, std::io::ErrorKind::PermissionDenied);
    assert_eq!(verdict, reconcile::ReconcileVerdict::Completed);
    std::fs::remove_dir_all(&root).unwrap();
}
